script:
.prose {
  color: var(--ink-gray-7);
  line-height: 1.75;
  font-size: 15px;
  word-break: break-word;
  overflow-wrap: break-word;
}

/* Keep content flush: no stray gap at the very top/bottom of the article */
.prose > :first-child {
  margin-top: 0;
}

.prose > :last-child {
  margin-bottom: 0;
}

.prose p {
  margin-top: 0;
  margin-bottom: 1em;
}

.prose h1 {
  color: #111827;
  font-weight: 800;
  font-size: 2.25em;
  margin-top: 0;
  margin-bottom: 0.8888889em;
  line-height: 1.1111111;
}

.prose h2 {
  color: #111827;
  font-weight: 700;
  font-size: 1.5em;
  margin-top: 2em;
  margin-bottom: 1em;
  line-height: 1.3333333;
}

.prose h3 {
  color: #111827;
  font-weight: 600;
  font-size: 1.25em;
  margin-top: 1.6em;
  margin-bottom: 0.6em;
  line-height: 1.6;
}

.prose h4 {
  color: #111827;
  font-weight: 600;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
  line-height: 1.5;
}

.prose h5 {
  color: #111827;
  font-weight: 600;
  font-size: 0.875em;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
  line-height: 1.5;
}

.prose h6 {
  color: #6b7280;
  font-weight: 600;
  font-size: 0.85em;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  margin-top: 1.5em;
  margin-bottom: 0.5em;
  line-height: 1.5;
}

/* A heading should hug the block that follows it */
.prose h1 + *,
.prose h2 + *,
.prose h3 + *,
.prose h4 + *,
.prose h5 + *,
.prose h6 + * {
  margin-top: 0;
}

.prose em {
  font-style: italic;
}

.prose strong {
  color: #111827;
  font-weight: 600;
}

.prose s,
.prose del {
  color: var(--ink-gray-6, #6b7280);
  text-decoration: line-through;
}

.prose a {
  color: #111827;
  text-decoration: underline;
  text-underline-offset: 2px;
  font-weight: 500;
}

.prose a:hover {
  color: #000;
  text-decoration-thickness: 2px;
}

.prose blockquote {
  font-weight: 500;
  font-style: italic;
  color: #111827;
  border-left-width: 0.25rem;
  border-left-color: #e5e7eb;
  margin-top: 1.6em;
  margin-bottom: 1.6em;
  padding-left: 1em;
}

.prose blockquote p {
  margin-top: 0.5em;
  margin-bottom: 0.5em;
}

.prose ul {
  list-style-type: disc;
  margin-top: 1.25em;
  margin-bottom: 1.25em;
  padding-left: 1.625em;
}

.prose ol {
  list-style-type: decimal;
  margin-top: 1.25em;
  margin-bottom: 1.25em;
  padding-left: 1.625em;
}

.prose li {
  margin-top: 0.5em;
  margin-bottom: 0.5em;
}

/* Nested lists: tighter spacing and varied markers */
.prose ul ul,
.prose ul ol,
.prose ol ul,
.prose ol ol {
  margin-top: 0.5em;
  margin-bottom: 0.5em;
}

.prose ul ul {
  list-style-type: circle;
}

.prose ul ul ul {
  list-style-type: square;
}

.prose ul li::marker {
  color: #e2e2e2;
}

.prose ol li::marker {
  color: #999;
}

.prose li p {
  margin-top: 0.25em;
  margin-bottom: 0.25em;
}

.prose hr {
  border-color: #e5e7eb;
  border-top-width: 1px;
  margin-top: 3em;
  margin-bottom: 3em;
}

/* Inline code (Code mark) */
.prose code {
  color: #24292e;
  background: #f6f8fa;
  border: 1px solid var(--outline-gray-2);
  border-radius: 4px;
  padding: 0.15em 0.4em;
  font-size: 0.85em;
  font-weight: 500;
  font-family:
    ui-monospace,
    Menlo,
    Monaco,
    Cascadia Mono,
    Segoe UI Mono,
    Roboto Mono,
    Oxygen Mono,
    Ubuntu Mono,
    Source Code Pro,
    Fira Mono,
    Droid Sans Mono,
    Consolas,
    Courier New,
    monospace;
}

/* Code block (CodeBlock node renders <pre><code>) */
.prose pre {
  color: #24292e;
  background: #f6f8fa;
  border: 1px solid var(--outline-gray-2);
  caret-color: #24292e;
  border-radius: 8px;
  padding: 0.75rem 1rem;
  margin-top: 1.5em;
  margin-bottom: 1.5em;
  overflow-x: auto;
  font-size: 12px;
  line-height: 1.7;
  font-family:
    ui-monospace,
    Menlo,
    Monaco,
    Cascadia Mono,
    Segoe UI Mono,
    Roboto Mono,
    Oxygen Mono,
    Ubuntu Mono,
    Source Code Pro,
    Fira Mono,
    Droid Sans Mono,
    Consolas,
    Courier New,
    monospace;
}

.prose pre code {
  background: transparent;
  border: 0;
  border-radius: 0;
  padding: 0;
  font-size: inherit;
  font-weight: inherit;
  color: inherit;
  white-space: pre;
}

/* Media */
.prose img,
.prose video {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
  margin-top: 2em;
  margin-bottom: 2em;
}

.prose figure {
  margin-top: 2em;
  margin-bottom: 2em;
}

.prose figure > img,
.prose figure > video {
  margin-top: 0;
  margin-bottom: 0;
}

.prose figcaption {
  color: var(--ink-gray-6, #6b7280);
  font-size: 0.875em;
  line-height: 1.4;
  margin-top: 0.75em;
  text-align: center;
}

.prose table {
  box-sizing: border-box;
  border-style: solid;
  border-width: 0;
  text-indent: 0;
  border-color: inherit;
  border-collapse: collapse;
  width: 100%;
  margin-top: 16px;
  margin-bottom: 16px;
  line-height: 1.7;
  table-layout: fixed;
  min-width: 75px;
}

.prose table thead {
  background-color: #fff;
}

.prose table tr {
  border-top: 1px solid #e5e7eb;
  border-bottom: 1px solid #e5e7eb;
}

.prose table th {
  background-color: var(--surface-gray-2);
  font-weight: 600;
}

.prose table th,
.prose table td {
  border-left: 1px solid #e5e7eb;
  border-right: 1px solid #e5e7eb;
  padding: 0.5rem;
  vertical-align: top;
  text-align: start;
}

/* Paragraphs sit flush inside table cells */
.prose table th > p,
.prose table td > p {
  margin-top: 0;
  margin-bottom: 0;
}

.prose ul[data-type="taskList"] {
  padding: 0;
  list-style: none;
}

.prose ul[data-type="taskList"] li {
  align-items: flex-start;
  margin: 0;
  display: flex;
}

.prose ul[data-type="taskList"] li > label {
  -webkit-user-select: none;
  user-select: none;
  flex: none;
  align-items: center;
  height: 1lh;
  margin-top: 0.25rem;
  margin-right: 0.5rem;
  display: flex;
}

.prose ul[data-type="taskList"] li > div {
  flex: auto;
  margin-bottom: 0;
}

.prose ul[data-type="taskList"] li > div > p {
  margin-top: 0;
  margin-bottom: 0;
}

.prose ul[data-type="taskList"] input[type="checkbox"] {
  cursor: pointer;
  color: #171717;
  border-radius: 4px;
  width: 14px;
  height: 14px;
}

/* Editor surface */
.prose:focus,
.prose:focus-visible {
  outline: none;
}

.prose ::selection {
  background: rgba(17, 24, 39, 0.12);
}

/* Selected media node inside the editor */
.prose .ProseMirror-selectednode {
  outline: 2px solid #111827;
  outline-offset: 2px;
}
